import{z as P,x as E,o as s,c as p,q as r,j as S,D as l,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"IS-IS","description":"","frontmatter":{"title":"IS-IS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/isis.md","filePath":"cs/isis.md","lastUpdated":1791063341000}'),I={name:"cs/isis.md"};function L(d,a,B,A,T,D){const i=E("Mermaid");return s(),p("div",null,[a[2]||(a[2]=r('<h1 id="is-is" tabindex="-1">IS-IS <a class="header-anchor" href="#is-is" aria-label="Permalink to &quot;IS-IS&quot;">​</a></h1><div class="epigraph"><p>IS-IS 同样洪泛链路状态、同样跑 SPF，但 PDU 走链路层，层级是 L1/L2，TLV 让它后来比 OSPFv2 更容易带新地址族。</p><footer>—— 据 ISO/IEC 10589；RFC 1195 把 IS-IS 用于 IP；RFC 5308 IPv6 整理</footer></div><p><a href="/cs/ospf-areas-lsa">上一课</a> 钉死 OSPF 区域。运营商骨干常跑 IS-IS。缺口是<strong>对照</strong>：不是再学一遍 Dijkstra，而是 CLNS 出身的两级层级、LSP 与 TLV。本课不把 RIP 计时器写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OSPF 是 IP 上的协议，依赖 IP 可达来传 LSA（邻接除外）。IS-IS Hello/LSP 可直接封装在二层，地址族可后加 TLV——历史上加 IPv6、SR 比 OSPFv2 补丁轻松。L1 像非骨干区域，L2 像骨干；L1/L2 路由器相当于 ABR。度量原 6 比特，宽度量后才适合 TE。</p><p><span class="marginnote">术语翻译：TLV 就是「类型-长度-值」三件套——先报这是什么（Type）、再报有多长（Length）、最后放内容（Value）；路由器遇到不认识的类型按 Length 跳过即可，这正是它后来能无痛加 IPv6 和 SR 的原因。</span></p><p>不要把 IS-IS 写成「二层路由替代 STP」：它算的是 IP（或 CLNS）下一跳，不是 MAC 洪泛树。</p><p><span class="marginnote">ISO 10589。RFC 1195 引入 IP。DIS 类似 DR 但广播网上选出。本课不背 NET 地址编码。</span></p><h3 id="二层-pdu-仍算-ip-下一跳" tabindex="-1">二层 PDU 仍算 IP 下一跳 <a class="header-anchor" href="#二层-pdu-仍算-ip-下一跳" aria-label="Permalink to &quot;二层 PDU 仍算 IP 下一跳&quot;">​</a></h3><p>不是 STP 替代。L1/L2 对应区域分层，TLV 方便加地址族与 SID。与 OSPF 选谁是生态，SPF 同构。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表：邻接、层级、扩展性、BFD 配套。画：L1 区 → L1/L2 → L2 骨干。与 OSPF 一样可 ECMP。承载 SR 前缀 SID 是后课，这里只承认 TLV 可扩展。</p>',12)),(s(),S(o,null,{default:l(()=>[n(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22L1%20LSP%20%E5%8C%BA%E5%86%85%22%5D%20--%3E%20L12%5B%22L1%2FL2%20%E8%BE%B9%E7%95%8C%22%5D%0A%20%20L12%20--%3E%20L2%5B%22L2%20%E9%AA%A8%E5%B9%B2%22%5D%0A%20%20TLV%5B%22TLV%20%E6%89%A9%E5%B1%95%22%5D%20--%3E%20AF%5B%22IPv4%2FIPv6%2FSR%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"主干链路状态课的洪泛可靠性（序号、老化）两边同构。选择哪一个往往是运维传统与 TE/SR 生态，不是容量公式。卫星高延迟链路上 Hello 死亡计时要放宽，与介质无关的协议定时器问题。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"为什么重要：卫星链路单程就有几百毫秒抖动，若照搬地面默认的「10 秒 Hello、30 秒判死」，一次抖动就可能误判邻居死亡，触发全网 SPF 重算——定时器必须随介质放宽。")],-1)),a[6]||(a[6]=e("p",null,"DIS 与 OSPF DR：都是减少广播网邻接全网状，细节不同，对象同类。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：广播网选出的 DIS 像班会里的「发言主持人」——大家只跟主持人对表，不必两两互相认识；n 台设备的邻接从 n(n−1)/2 条降到约 n 条，比如 10 台从 45 条降到 10 条。")],-1)),a[8]||(a[8]=e("p",null,"一条 LSP 里 TLV 如何实现向前兼容：",-1)),(s(),S(o,null,{default:l(()=>[n(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20LSP%5B%22%E4%B8%80%E4%B8%AA%20IS-IS%20LSP%22%5D%20--%3E%20H%5B%22%E5%9B%BA%E5%AE%9A%E5%A4%B4%E9%83%A8%22%5D%0A%20%20LSP%20--%3E%20T1%5B%22TLV%3A%20IS%20%E9%82%BB%E5%B1%85%22%5D%0A%20%20LSP%20--%3E%20T2%5B%22TLV%3A%20IPv4%20%E5%89%8D%E7%BC%80%22%5D%0A%20%20LSP%20--%3E%20T3%5B%22TLV%3A%20IPv6%20%E5%89%8D%E7%BC%80%EF%BC%88%E5%90%8E%E5%8A%A0%EF%BC%89%22%5D%0A%20%20LSP%20--%3E%20T4%5B%22TLV%3A%20SR%20SID%EF%BC%88%E5%90%8E%E5%8A%A0%EF%BC%89%22%5D%0A%20%20T3%20--%3E%20OLD%5B%22%E8%80%81%E8%B7%AF%E7%94%B1%E5%99%A8%E6%8C%89%20Length%20%E8%B7%B3%E8%BF%87%EF%BC%8C%E7%85%A7%E5%B8%B8%E8%BD%AC%E5%8F%91%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IS-IS 多拓扑的全部。RIP 对照是下一课。后课默认：域内链路状态有 OSPF 与 IS-IS 两套互操作栈，SPF 相同。</p><p>不要同时在同一链路上跑两套无必要的 IGP。</p><p>下一课<a href="/cs/rip">RIP 对照</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IS-IS：二层 PDU、L1/L2、TLV 扩展。</li><li>计算仍是 SPF，不是距离向量。</li><li>与 OSPF 分工是工程生态，不是对错。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ISO 10589；RFC 1195；RFC 5308。</li></ul>',6))])}const F=P(I,[["render",L]]);export{u as __pageData,F as default};
